package org.com.sharekhan.migration;
import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.com.sharekhan.entity.*;import org.com.sharekhan.repository.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Component;
@Component @Slf4j @RequiredArgsConstructor @ConditionalOnExpression("'${app.reference-data.postgres.enabled:false}' == 'true' and '${app.reference-data.postgres.backfill-on-startup:false}' == 'true'")
public class ReferenceDataBackfillRunner implements ApplicationRunner{private final ScriptMasterRepository scripts;private final MStockInstrumentRepository mstock;private final ShoonyaInstrumentRepository shoonya;@Qualifier("auditPostgresJdbcTemplate") private final NamedParameterJdbcTemplate pg;public void run(ApplicationArguments a){copy("script_master","scrip_code,trading_symbol,exchange,instrument_type,strike_price,expiry,lot_size,option_type",":scripCode,:tradingSymbol,:exchange,:instrumentType,:strikePrice,:expiry,:lotSize,:optionType",scripts.findAll());copy("mstock_instrument_master","instrument_token,instrument_key,trading_symbol,name,exchange,segment,instrument_type,exchange_token,last_price,expiry,strike,tick_size,lot_size,fetched_at",":instrumentToken,:instrumentKey,:tradingSymbol,:name,:exchange,:segment,:instrumentType,:exchangeToken,:lastPrice,:expiry,:strike,:tickSize,:lotSize,:fetchedAt",mstock.findAll());copy("shoonya_instrument_master","id,instrument_key,exchange,token,trading_symbol,symbol,expiry,instrument,option_type,strike_price,lot_size,tick_size,fetched_at",":id,:instrumentKey,:exchange,:token,:tradingSymbol,:symbol,:expiry,:instrument,:optionType,:strikePrice,:lotSize,:tickSize,:fetchedAt",shoonya.findAll());if(count("script_master")!=scripts.count()||count("mstock_instrument_master")!=mstock.count()||count("shoonya_instrument_master")!=shoonya.count())throw new IllegalStateException("Reference data backfill count mismatch");log.info("PostgreSQL reference-data backfill complete: scripts={} mstock={} shoonya={}",scripts.count(),mstock.count(),shoonya.count());}private void copy(String t,String c,String v,java.util.List<?>r){if(r.isEmpty())return;pg.batchUpdate("INSERT INTO "+t+" ("+c+") OVERRIDING SYSTEM VALUE VALUES ("+v+") ON CONFLICT DO NOTHING",r.stream().map(BeanPropertySqlParameterSource::new).toArray(SqlParameterSource[]::new));}private long count(String t){Long n=pg.getJdbcTemplate().queryForObject("SELECT COUNT(*) FROM "+t,Long.class);return n==null?0:n;}}
